let likesLeft = 30;
let isLiking = false;
document.querySelector('.btn.like').addEventListener('click', () => {
  if (isLiking) return;
  isLiking = true;
  const btn = document.querySelector('.btn.like');
  const p = profiles[currentIndex];
  if (!p) { isLiking = false; return; }
  if (likesLeft <= 0) { alert('Out of likes for today!'); isLiking = false; return; }
  if (!likedProfiles.find(x => x.name === p.name)) {
    likedProfiles.push(p);
    try { localStorage.setItem('whisper_liked', JSON.stringify(likedProfiles)); } catch(e) {}
    likesLeft--;
    try { localStorage.setItem('whisper_likes_left', String(likesLeft)); } catch(e) {}
    if (typeof updateLikesCircle === 'function') updateLikesCircle();
    var _c=document.getElementById('likes-count'); if(_c) _c.textContent=likesLeft;
    if (typeof showLiked === 'function') showLiked();
  }
  btn.textContent = 'Liked \u2764\ufe0f';
  btn.disabled = true;
  setTimeout(() => {
    btn.textContent = 'Like';
    btn.disabled = false;
    isLiking = false;
    nextProfile();
  }, 450);
});
