(function(){
  try{
    var saved = parseInt(localStorage.getItem('whisper_likes_left'), 10);
    if(!isNaN(saved)) likesLeft = saved;
    try{ updateLikesCircle(); }catch(e){}
  }catch(e){}
  function skip(){
    while(currentIndex < profiles.length && likedProfiles.find(function(x){return x.name===profiles[currentIndex].name;})){
      currentIndex++;
    }
    if(currentIndex >= profiles.length) currentIndex = 0;
    showProfile(currentIndex);
    try{ showLiked(); updateLikesCircle(); }catch(e){}
  }
  document.addEventListener('DOMContentLoaded', function(){ setTimeout(skip, 100); });
  setTimeout(skip, 600);
})();
// ---- MAP TAB - SIMPLE ----
let mapFilter = 'all';
function initWhisperMap(){}
// City -> approx lat/lng so pins always show even if profile has no coords
const CITY_POS = {'Lagos':[6.45,3.39],'Abuja':[9.06,7.48],'Accra':[5.6,-0.18],'Douala':[4.05,9.7],'Yaounde':[3.86,11.51],'Malabo':[3.75,8.78],'Nairobi':[-1.29,36.82],'Johannesburg':[-26.2,28.04],'Cairo':[30.04,31.23],'London':[51.5,-0.12],'Paris':[48.85,2.35],'New York':[40.71,-74.0],'Los Angeles':[34.05,-118.24],'Toronto':[43.65,-79.38],'Dubai':[25.2,55.27],'Mumbai':[19.07,72.87],'Tokyo':[35.67,139.69],'Sydney':[-33.86,151.2],'Berlin':[52.52,13.4],'Madrid':[40.41,-3.7]};
function posFor(p){
  if(p.lat && p.lng) return [p.lat,p.lng];
  for(const k in CITY_POS){ if((p.location||'').includes(k)) return CITY_POS[k]; }
  return [10,10];
}
let mapZoom=1, mapX=0, mapY=0;
function applyMapZoom(){
  const layer=document.getElementById('pins-layer'); if(!layer) return;
  layer.style.transform='translate('+mapX+'px,'+mapY+'px) scale('+mapZoom+')';
  layer.style.transformOrigin='center center';
}
function renderSimplePins(people){
  const el=document.getElementById('simple-map');
  if(!el) return;
  let layer=document.getElementById('pins-layer');
  if(!layer){ layer=document.createElement('div'); layer.id='pins-layer'; layer.style.cssText='position:absolute;inset:0;'; el.appendChild(layer); }
  layer.innerHTML='';
  // debug badge - you should see "XX pins"
  const badge=document.createElement('div');
  badge.textContent=people.length+' pins';
  badge.style.cssText='position:absolute;bottom:10px;left:10px;background:black;color:white;padding:6px 10px;border-radius:999px;font-size:12px;z-index:20;';
  layer.appendChild(badge);
  people.slice(0,60).forEach(person=>{
    const [la,lo]=posFor(person);
    const x=(lo+180)/360*100;
    const y=(90-la)/180*100;
    const d=document.createElement('div');
    d.innerHTML='<img src="'+person.img+'" style="width:42px;height:42px;border-radius:50%;border:3px solid white;box-shadow:0 2px 8px rgba(0,0,0,.5);object-fit:cover;display:block;">';
    d.style.cssText='position:absolute;left:'+x+'%;top:'+y+'%;transform:translate(-50%,-50%);z-index:5;';
    d.onclick=()=>{ const idx=profiles.indexOf(person); if(idx>=0){ currentIndex=idx; showProfile(idx); document.querySelectorAll('.nav-btn').forEach(b=>b.classList.remove('active')); document.querySelectorAll('.screen').forEach(s=>s.classList.remove('active')); document.getElementById('discover').classList.add('active'); document.querySelector('[data-screen="discover"]').classList.add('active'); } };
    layer.appendChild(d);
  });
  applyMapZoom();
}
// pinch removed - map is now simple and clickable
let mapCity = '';
function getMapPeople(){
  let list = profiles.slice();
  if(mapFilter === 'online') list = list.filter((_,i)=> i % 2 === 0);
  if(mapFilter === 'near') list = list.filter(p => p.location.includes('Nigeria') || p.location.includes('Cameroon') || p.location.includes('Ghana'));
  if(mapCity){
    const q = mapCity.toLowerCase();
    const byCity = list.filter(p => p.location.toLowerCase().includes(q));
    if(byCity.length) list = byCity;
  }
  return list;
}
function renderMap(){
  const listEl = document.getElementById('map-list');
  const pinsEl = document.getElementById('map-pins');
  const countEl = document.getElementById('map-count');
  const emptyEl = document.getElementById('map-empty');
  const labelEl = document.getElementById('map-center-label');
  if(!listEl) return;
  const people = getMapPeople();
  if(labelEl) labelEl.textContent = mapCity || 'World';
  if(countEl) countEl.textContent = people.length + ' people';
  if(emptyEl) emptyEl.style.display = people.length ? 'none' : 'block';
  if(pinsEl){ pinsEl.innerHTML=''; }
  renderSimplePins(people);
  // NO auto-pan here - user controls map. Pan only on search (see below).
  listEl.innerHTML = '';
  people.forEach((person)=>{
    const row = document.createElement('div');
    row.style.cssText = 'display:flex;gap:10px;align-items:center;background:white;padding:10px;border-radius:15px;';
    row.innerHTML = '<img src="'+person.img+'" style="width:50px;height:50px;border-radius:50%;object-fit:cover;"><div style="flex:1;"><strong>'+person.name+'</strong><br><span style="color:#888;font-size:13px;">'+person.location+'</span><br><span style="font-size:13px;">'+person.bio+'</span></div><button style="background:#6C63FF;color:white;border:none;padding:8px 14px;border-radius:20px;font-weight:bold;">View</button>';
    row.querySelector('button').onclick = ()=>{ const idx = profiles.indexOf(person); if(idx>=0){ currentIndex = idx; showProfile(idx); document.querySelectorAll(".nav-btn").forEach(b=>b.classList.remove("active")); document.querySelectorAll(".screen").forEach(s=>s.classList.remove("active")); document.getElementById("discover").classList.add("active"); document.querySelector('[data-screen="discover"]').classList.add("active"); } };
    listEl.appendChild(row);
  });
}
document.addEventListener('click', function(e){
  if(e.target && e.target.classList && e.target.classList.contains('map-filter')){
    mapFilter = e.target.getAttribute('data-filter');
    document.querySelectorAll('.map-filter').forEach(b=>{ b.style.background='#eee'; b.style.color='black'; });
    e.target.style.background='#6C63FF'; e.target.style.color='white';
    renderMap();
  }
  if(e.target && e.target.id === 'map-search-btn'){
    const v = document.getElementById('map-search').value.trim();
    if(v){ mapCity = v; renderMap(); var _f=getMapPeople().find(p=>p.location.toLowerCase().includes(v.toLowerCase())); if(_f && whisperMap) whisperMap.setView([_f.lat,_f.lng],6); }
  }
});
